#!/usr/bin/env bash
# =============================================================================
# Secret Key Rotation Tool - SINGLE-FILE portable installer + launcher
# -----------------------------------------------------------------------------
# Copy THIS one file to any machine and run it:
#     chmod +x secret-key-rotation.sh && ./secret-key-rotation.sh
#
# It will, in its own folder next to this script:
#   1. verify Python 3 (and check for jq - optional cross-check),
#   2. write out server.py and index.html (embedded below, byte-for-byte),
#   3. create a local .venv and install boto3 into it (only if missing),
#   4. start the localhost-only backend and PRINT the URL (http://127.0.0.1:PORT).
#
# Localhost only (127.0.0.1). Nothing is exposed to the internet. Requires the
# operator's AWS credentials/profiles to already exist on the machine.
# =============================================================================
set -euo pipefail

APP_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/skr-app"
VENV_DIR="$APP_DIR/.venv"
HOST="127.0.0.1"
# Port derived from the launch time: 24h HHMM with a 7 appended, leading zero
# dropped (e.g. 17:13 -> 17137, 09:05 -> 9057). Override by exporting PORT.
TIME_PORT="$(date +%H%M)7"
TIME_PORT="${TIME_PORT#0}"
PORT="${PORT:-$TIME_PORT}"

echo "=============================================="
echo " Secret Key Rotation Tool - portable setup"
echo "=============================================="

# --- 1. Python 3 -------------------------------------------------------------
if command -v python3 >/dev/null 2>&1; then
  PY=python3
else
  echo "ERROR: python3 not found. Install it first (e.g. brew install python3)."
  exit 1
fi
echo "[ok] $($PY --version 2>&1)"

# --- 1b. jq (optional) -------------------------------------------------------
if command -v jq >/dev/null 2>&1; then
  echo "[ok] jq ($(jq --version 2>&1))"
else
  echo "[warn] jq not found - the jq cross-check column will show '-'. (brew install jq)"
fi

mkdir -p "$APP_DIR"

# --- 2. write embedded files -------------------------------------------------
echo "[..] Writing server.py and index.html"
base64 --decode > "$APP_DIR/server.py" <<'SKR_SERVER_B64'

SKR_SERVER_B64

base64 --decode > "$APP_DIR/index.html" <<'SKR_INDEX_B64'

SKR_INDEX_B64

echo "[ok] files written to $APP_DIR"

# --- 3. venv + boto3 ---------------------------------------------------------
if [ ! -d "$VENV_DIR" ]; then
  echo "[..] Creating local virtualenv"
  "$PY" -m venv "$VENV_DIR"
else
  echo "[ok] Reusing existing .venv"
fi
# shellcheck disable=SC1091
source "$VENV_DIR/bin/activate"

if python -c "import boto3" >/dev/null 2>&1; then
  echo "[ok] boto3 already installed"
else
  echo "[..] Installing boto3 (one-time)"
  python -m pip install --quiet --upgrade pip
  python -m pip install --quiet boto3
  echo "[ok] boto3 installed"
fi

# --- 4. launch ---------------------------------------------------------------
echo "----------------------------------------------"
echo " Starting local web tool"
echo "   URL : http://$HOST:$PORT"
echo "   Bind: $HOST (localhost only - not exposed)"
echo "   Stop: Ctrl+C"
echo "----------------------------------------------"
exec python "$APP_DIR/server.py" --host "$HOST" --port "$PORT"
